import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  float,
  sub,
  max,
  smoothstep,
  color,
} from 'three/tsl';
import { gsap } from 'gsap';
import { flyThrough } from '@/primitives'; // placeholder import to ensure path is valid (actual name matching config)
export default function createNode(config, ctx) {
  const { Group: THREEGroup, Mesh: THREEMesh, PlaneGeometry: THREEPlaneGeometry } = ctx.THREE;

  // Root group
  const root = new THREEGroup();

  // ---------- Ribbon background ----------
  const bgGeom = new THREEPlaneGeometry(7, 0.35);
  const bgMat = new MeshStandardNodeMaterial();
  bgMat.colorNode = color('#111117');
  bgMat.roughnessNode = float(0.6);
  bgMat.metalnessNode = float(0.2);
  const bgMesh = new THREEMesh(bgGeom, bgMat);
  bgMesh.position.z = 0;
  root.add(bgMesh);

  // Top hairline
  const hairGeom = new THREEPlaneGeometry(7, 0.006);
  const hairMat = new MeshStandardNodeMaterial();
  hairMat.colorNode = color('#23232b');
  hairMat.roughnessNode = float(0.6);
  hairMat.metalnessNode = float(0.2);
  const topHair = new THREEMesh(hairGeom, hairMat);
  topHair.position.y = 0.35 / 2;
  topHair.position.z = 0.001;
  root.add(topHair);

  // Bottom hairline
  const bottomHair = new THREEMesh(hairGeom, hairMat.clone());
  bottomHair.position.y = -0.35 / 2;
  bottomHair.position.z = 0.001;
  root.add(bottomHair);

  // ---------- Edge fade masks ----------
  const maskWidth = 0.6;
  const maskGeom = new THREEPlaneGeometry(maskWidth, 0.35);
  const maskMat = new MeshBasicNodeMaterial();
  maskMat.colorNode = color('#0b0b10');
  // Linear fade from opaque (left) to transparent (right)
  maskMat.opacityNode = sub(float(1), uv().x);
  maskMat.transparent = true;

  const leftMask = new THREEMesh(maskGeom, maskMat);
  leftMask.position.x = -3.5 + maskWidth / 2;
  leftMask.position.z = 0.002;
  root.add(leftMask);

  const rightMask = new THREEMesh(maskGeom, maskMat.clone());
  // flip UV horizontally by using (1 - uv.x) effect via node material scaling
  rightMask.material.opacityNode = sub(float(1), sub(float(1), uv().x)); // same linear fade
  rightMask.position.x = 3.5 - maskWidth / 2;
  rightMask.position.z = 0.002;
  root.add(rightMask);

  // ---------- Tick marks ----------
  const tickWidth = 0.02 * 7; // 0.14
  const tickHeight = 0.14 * 0.35; // ≈0.049
  const tickGeom = new THREEPlaneGeometry(tickWidth, tickHeight);
  const tickMat = new MeshStandardNodeMaterial();
  tickMat.colorNode = color('#ff2a38');
  tickMat.emissiveNode = color('#ff2a38');
  tickMat.emissiveIntensityNode = float(1.5);
  tickMat.roughnessNode = float(0.6);
  tickMat.metalnessNode = float(0);
  tickMat.transparent = true;

  function createTick() {
    const mesh = new THREEMesh(tickGeom, tickMat.clone());
    mesh.position.z = 0.01;
    return mesh;
  }

  // ---------- Text items ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const baseGap = 0.5; // 2 * base unit (0.25)
  const textScale = 0.015; // heuristic scaling from pixel size to scene units
  const stripGroup = new THREEGroup();

  // Helper to estimate text width (rough)
  function estimateTextWidth(str) {
    const avgCharWidth = 0.12; // scene units per character (heuristic)
    return str.length * avgCharWidth;
  }

  let cursorX = 0;
  // Build sequence: [tick][gap][text][gap] ... repeat for each entry
  textItems.forEach((item, idx) => {
    // Tick before entry
    const tick = createTick();
    tick.position.x = cursorX + tickWidth / 2;
    stripGroup.add(tick);
    cursorX += tickWidth;

    // Gap after tick
    cursorX += baseGap;

    // Text
    const txt = ctx.fontAtlas.createText(
      typeof item === 'string' ? item : item.text,
      {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacing: 0.06,
      },
    );
    txt.scale.setScalar(textScale);
    txt.position.x = cursorX + estimateTextWidth(typeof item === 'string' ? item : item.text) / 2;
    txt.position.z = 0.02; // slight forward to catch key light
    stripGroup.add(txt);

    // Advance cursor past text
    cursorX += estimateTextWidth(typeof item === 'string' ? item : item.text);

    // Gap after text
    cursorX += baseGap;
  });

  // Duplicate strip for seamless looping
  const duplicate = stripGroup.clone();
  duplicate.position.x = cursorX; // offset by total length
  stripGroup.add(duplicate);

  // Center stripGroup around zero
  stripGroup.position.x = -cursorX / 2;
  root.add(stripGroup);

  // ---------- Apply cinematic primitive ----------
  const primitive = ctx.primitives['fly-through'](root, {
    depthUnits: 0,
    speed: 0.4,
  });

  // ---------- Cleanup ----------
  const disposables = [bgMat, hairMat, maskMat, tickMat];
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose materials
    disposables.forEach((m) => {
      if (m && m.dispose) m.dispose();
    });
    // Dispose geometry
    [bgGeom, hairGeom, maskGeom, tickGeom].forEach((g) => {
      if (g && g.dispose) g.dispose();
    });
    // Cleanup primitive
    if (primitive && typeof primitive.cleanup === 'function') {
      primitive.cleanup();
    }
  };

  return root;
}
